/**
 * GENERATED FILE — run `node tools/generate-meme-fonts.mjs` to refresh.
 *
 * Latin woff2 subsets inlined for the meme renderer. Exported memes are
 * standalone SVG documents, so any face that is not embedded here falls back to
 * whatever the viewer happens to have installed.
 */

export interface EmbeddedFace {
  family: string;
  weight: number;
  style: string;
  /** base64-encoded woff2, latin subset. */
  data: string;
}

export type EmbeddedFaceId =
  | 'anton400'
  | 'inter400'
  | 'inter700'
  | 'cormorant600'
  | 'cormorant600Italic'
  | 'bodoni700';

export const EMBEDDED_FACES: Record<EmbeddedFaceId, EmbeddedFace> = {
  anton400: {
    family: 'Anton',
    weight: 400,
    style: 'normal',
    data: '',
  },
  inter400: {
    family: 'Inter',
    weight: 400,
    style: 'normal',
    data: '',
  },
  inter700: {
    family: 'Inter',
    weight: 700,
    style: 'normal',
    data: '',
  },
  cormorant600: {
    family: 'Cormorant Garamond',
    weight: 600,
    style: 'normal',
    data: '',
  },
  cormorant600Italic: {
    family: 'Cormorant Garamond',
    weight: 600,
    style: 'italic',
    data: '',
  },
  bodoni700: {
    family: 'Bodoni Moda',
    weight: 700,
    style: 'normal',
    data: '',
  },
};

/** `@font-face` CSS for the given faces, ready to drop into an SVG <style>. */
export function fontFaceCss(ids: Iterable<EmbeddedFaceId>): string {
  const seen = new Set<EmbeddedFaceId>();
  const rules: string[] = [];
  for (const id of ids) {
    if (seen.has(id)) continue;
    seen.add(id);
    const face = EMBEDDED_FACES[id];
    if (!face) continue;
    rules.push(
      `@font-face{font-family:'${face.family}';font-style:${face.style};font-weight:${face.weight};font-display:block;src:url(data:font/woff2;base64,${face.data}) format('woff2');}`,
    );
  }
  return rules.join('');
}
